select jsonb_build_object(
 'system_identifier',(select system_identifier::text from pg_catalog.pg_control_system()),
 'history_count',(select count(*) from supabase_migrations.schema_migrations),
 'latest_version',(select max(version) from supabase_migrations.schema_migrations),
 'full_history',(select jsonb_agg(jsonb_build_object('version',version,'name',name,'statements_count',case when statements is null then null else coalesce(array_length(statements,1),0) end,'statements_sha256',case when statements is null then null else encode(sha256(convert_to(array_to_string(statements,E'\n'),'UTF8')),'hex') end) order by version) from supabase_migrations.schema_migrations),
 'functions',(select coalesce(jsonb_agg(jsonb_build_object('s',p.oid::regprocedure::text,'d',md5(pg_get_functiondef(p.oid)),'o',p.proowner::regrole::text,'a',p.proacl::text) order by p.oid::regprocedure::text),'[]') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private','auth') and p.prokind in ('f','p') and not exists (select 1 from pg_depend d where d.classid='pg_proc'::regclass and d.objid=p.oid and d.deptype='e')),
 'relations',(select coalesce(jsonb_agg(jsonb_build_object('n',n.nspname||'.'||c.relname,'k',c.relkind,'rls',c.relrowsecurity,'f',c.relforcerowsecurity,'o',c.relowner::regrole::text,'a',c.relacl::text) order by n.nspname,c.relname),'[]') from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private','auth') and c.relkind in ('r','p','v','m','S','f')),
 'indexes',(select coalesce(jsonb_agg(jsonb_build_object('n',n.nspname||'.'||c.relname,'d',md5(pg_get_indexdef(i.indexrelid)),'v',i.indisvalid) order by n.nspname,c.relname),'[]') from pg_index i join pg_class c on c.oid=i.indexrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private','auth')),
 'triggers',(select coalesce(jsonb_agg(jsonb_build_object('n',n.nspname||'.'||c.relname||'.'||t.tgname,'d',md5(pg_get_triggerdef(t.oid)),'e',t.tgenabled) order by n.nspname,c.relname,t.tgname),'[]') from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where not t.tgisinternal and n.nspname in ('public','private','auth')),
 'policies',(select coalesce(jsonb_agg(jsonb_build_object('n',schemaname||'.'||tablename||'.'||policyname,'d',md5(concat_ws('|',permissive,roles::text,cmd,qual,with_check))) order by schemaname,tablename,policyname),'[]') from pg_policies where schemaname in ('public','private','auth','storage')),
 'cron',(select coalesce(jsonb_agg(jsonb_build_object('n',jobname,'s',schedule,'c',md5(command),'u',username,'a',active,'db',database) order by jobname,jobid),'[]') from cron.job),
 'lifecycle_review',(select coalesce(jsonb_agg(to_jsonb(r) order by kind,schema_name,table_name,object_name),'[]') from private.account_lifecycle_trigger_review r),
 'lifecycle_surface',(select coalesce(jsonb_agg(to_jsonb(s) order by kind,schema_name,table_name,object_name),'[]') from inlined_surface s),
 'trigger_review_issues',(select count(*) from inlined_issues),
 'login_status',jsonb_build_object('roles',(select count(*) from pg_roles where rolname like 'cli_login_%' and (rolvaliduntil is null or rolvaliduntil>now()))),
 'vault_names',(select coalesce(jsonb_agg(name order by name),'[]') from vault.secrets where name in ('task-files-reconcile-secret','notifications-dispatch-secret')),
 'controls',(select jsonb_build_object('files_url_set',files_reconcile_url is not null,'dispatch_url_set',dispatch_url is not null) from private.notification_controls where id),
 'constraints',(select coalesce(jsonb_agg(jsonb_build_object('n',n.nspname||'.'||t.relname||'.'||c.conname,'d',md5(pg_get_constraintdef(c.oid)),'v',c.convalidated) order by n.nspname,t.relname,c.conname),'[]') from pg_constraint c join pg_class t on t.oid=c.conrelid join pg_namespace n on n.oid=t.relnamespace where n.nspname in ('public','private')),
 'columns',(select coalesce(jsonb_agg(jsonb_build_object('n',table_schema||'.'||table_name||'.'||column_name,'t',data_type,'null',is_nullable,'def',md5(coalesce(column_default,''))) order by table_schema,table_name,column_name),'[]') from information_schema.columns where table_schema in ('public','private'))
)
